import { useEffect, useState } from "react";
import { ME } from "../lib/contacts";
import { formatSize } from "../lib/format";
import { useIsMobile, useIsNarrow } from "../lib/hooks";
import { navigate } from "../lib/router";
import { useMail } from "../lib/store";
import type { Theme } from "../lib/types";
import { useUI } from "../lib/ui";
import { cn } from "../lib/utils";
import { SearchBar } from "./SearchBar";
import { Avatar, Icon, IconButton, Popover, useMenu } from "./ui";

export const APP_TITLE = "Claude Opus 5.5";

export function Logo({ compact }: { compact?: boolean }) {
  return (
    <a
      href="#inbox"
      onClick={(e) => {
        e.preventDefault();
        navigate("#inbox");
      }}
      className="flex min-w-0 items-center gap-2.5 rounded-lg pr-2"
      aria-label={APP_TITLE}
    >
      <svg viewBox="0 0 48 48" className="h-8 w-8 shrink-0" aria-hidden>
        <defs>
          <linearGradient id="lg-logo" x1="0" y1="0" x2="1" y2="1">
            <stop offset="0" stopColor="#4f7cff" />
            <stop offset="1" stopColor="#1a4fd6" />
          </linearGradient>
        </defs>
        <rect x="3" y="9" width="42" height="31" rx="7" fill="url(#lg-logo)" />
        <path d="M6 14l18 13 18-13" fill="none" stroke="#fff" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round" />
        <circle cx="39" cy="12" r="6" fill="#ff7a59" stroke="var(--app-bg)" strokeWidth="2.5" />
      </svg>
      {!compact && <h1 className="whitespace-nowrap font-display text-[20px] leading-none tracking-tight text-fg-2">{APP_TITLE}</h1>}
    </a>
  );
}

export function TopBar() {
  const isMobile = useIsMobile();
  const isNarrow = useIsNarrow();
  const collapsed = useMail((s) => s.settings.sidebarCollapsed);
  const updateSettings = useMail((s) => s.updateSettings);
  const setNavOpen = useUI((s) => s.setNavOpen);
  const setSettingsOpen = useUI((s) => s.setSettingsOpen);
  const settingsOpen = useUI((s) => s.settingsOpen);
  const openDialog = useUI((s) => s.openDialog);
  const [mobileSearch, setMobileSearch] = useState(false);

  if (isMobile) {
    if (mobileSearch) {
      return (
        <header className="flex h-16 shrink-0 items-center px-2">
          <SearchBar autoFocus onClose={() => setMobileSearch(false)} />
        </header>
      );
    }
    return (
      <header className="flex h-16 shrink-0 items-center gap-1 px-2">
        <IconButton icon="menu" label="Main menu" size="lg" onClick={() => setNavOpen(true)} />
        <div className="min-w-0 flex-1">
          <Logo />
        </div>
        <IconButton icon="search" label="Search mail" size="lg" onClick={() => setMobileSearch(true)} />
        <AccountButton />
      </header>
    );
  }

  return (
    <header className="flex h-16 shrink-0 items-center gap-2 pl-2 pr-3">
      <div className={cn("flex shrink-0 items-center gap-1", isNarrow ? "w-auto" : "w-[248px]")}>
        <IconButton
          icon="menu"
          label="Main menu"
          size="lg"
          onClick={() => (isNarrow ? setNavOpen(true) : updateSettings({ sidebarCollapsed: !collapsed }))}
        />
        <Logo />
      </div>
      <div className="flex min-w-0 flex-1 items-center pl-2">
        <SearchBar />
      </div>
      <div className="flex shrink-0 items-center gap-0.5 pl-2">
        <OnlineStatus />
        <IconButton icon="help" label="Keyboard shortcuts" onClick={() => openDialog({ type: "shortcuts" })} />
        <IconButton icon="settings" label="Settings" active={settingsOpen} onClick={() => setSettingsOpen(!settingsOpen)} />
        <AccountButton />
      </div>
    </header>
  );
}

function OnlineStatus() {
  const [online, setOnline] = useState(navigator.onLine);
  useEffect(() => {
    const on = () => setOnline(true);
    const off = () => setOnline(false);
    window.addEventListener("online", on);
    window.addEventListener("offline", off);
    return () => {
      window.removeEventListener("online", on);
      window.removeEventListener("offline", off);
    };
  }, []);
  return (
    <div
      data-tip={online ? "Changes are saved in this browser" : "You're offline. Changes are still saved locally."}
      className="mr-1 hidden h-9 items-center gap-1.5 rounded-full border border-line px-3 text-xs text-fg-2 lg:flex"
    >
      <span className={cn("h-2 w-2 rounded-full", online ? "bg-[#1e8e3e]" : "bg-[#f29900]")} />
      {online ? "Saved locally" : "Offline"}
    </div>
  );
}

function storageUsed() {
  let total = 0;
  for (let i = 0; i < localStorage.length; i++) {
    const k = localStorage.key(i)!;
    total += (localStorage.getItem(k)?.length ?? 0) * 2;
  }
  return total;
}

function AccountButton() {
  const menu = useMenu();
  const theme = useMail((s) => s.settings.theme);
  const updateSettings = useMail((s) => s.updateSettings);
  const resetDemo = useMail((s) => s.resetDemo);
  const threads = useMail((s) => s.threads);
  const openDialog = useUI((s) => s.openDialog);
  const setSettingsOpen = useUI((s) => s.setSettingsOpen);
  const showToast = useUI((s) => s.showToast);
  const used = menu.open ? storageUsed() : 0;
  const quota = 5 * 1024 * 1024;

  return (
    <>
      <button
        ref={menu.ref}
        type="button"
        onClick={menu.toggle}
        aria-label={`Account: ${ME.name} (${ME.email})`}
        data-tip={`${ME.name}\n${ME.email}`}
        className={cn("ml-1 flex h-10 w-10 items-center justify-center rounded-full hover:bg-hover", menu.open && "bg-hover")}
      >
        <Avatar name={ME.name} email={ME.email} size={32} />
      </button>
      <Popover anchor={menu.ref.current} open={menu.open} onClose={menu.close} align="end" className="w-[360px] max-w-[calc(100vw-16px)] rounded-[28px] bg-surface-3 p-3">
        <div className="relative px-2 pb-3 pt-1 text-center">
          <div className="text-sm font-medium text-fg-2">{ME.email}</div>
          <IconButton icon="close" label="Close" size="sm" className="absolute right-0 top-0" onClick={menu.close} />
          <div className="mt-4 flex justify-center">
            <Avatar name={ME.name} email={ME.email} size={76} />
          </div>
          <div className="mt-3 font-display text-[22px]">Hi, {ME.name.split(" ")[0]}!</div>
          <div className="mt-1 text-sm text-fg-3">
            {Object.keys(threads).length} conversations · Product Lead at Lumen Labs
          </div>
        </div>
        <div className="overflow-hidden rounded-3xl bg-raised">
          <div className="px-5 pb-2 pt-4 text-xs font-medium uppercase tracking-wider text-fg-3">Theme</div>
          <div className="mx-4 mb-3 grid grid-cols-3 gap-1 rounded-full bg-surface-3 p-1">
            {(["light", "dark", "system"] as Theme[]).map((t) => (
              <button
                key={t}
                type="button"
                onClick={() => updateSettings({ theme: t })}
                className={cn(
                  "flex h-8 items-center justify-center gap-1.5 rounded-full text-sm capitalize",
                  theme === t ? "bg-raised font-medium text-fg shadow-sm" : "text-fg-2 hover:bg-hover",
                )}
              >
                <Icon name={t === "light" ? "light_mode" : t === "dark" ? "dark_mode" : "contrast"} size={16} />
                {t}
              </button>
            ))}
          </div>
          <div className="h-px bg-line" />
          <button
            type="button"
            onClick={() => {
              menu.close();
              setSettingsOpen(true);
            }}
            className="flex h-12 w-full items-center gap-4 px-5 text-left text-sm hover:bg-hover"
          >
            <Icon name="settings" className="text-fg-2" /> Quick settings
          </button>
          <button
            type="button"
            onClick={() => {
              menu.close();
              openDialog({ type: "shortcuts" });
            }}
            className="flex h-12 w-full items-center gap-4 px-5 text-left text-sm hover:bg-hover"
          >
            <Icon name="keyboard" className="text-fg-2" /> Keyboard shortcuts
          </button>
          <button
            type="button"
            onClick={() => {
              menu.close();
              openDialog({
                type: "confirm",
                title: "Reset demo mailbox?",
                body: "All changes (sent mail, drafts, labels, settings) will be replaced with the original seeded mailbox.",
                confirmLabel: "Reset mailbox",
                danger: true,
                onConfirm: () => {
                  resetDemo();
                  useUI.getState().clearSelection();
                  navigate("#inbox");
                  showToast({ message: "Mailbox reset to the original demo data." });
                },
              });
            }}
            className="flex h-12 w-full items-center gap-4 px-5 text-left text-sm hover:bg-hover"
          >
            <Icon name="restart_alt" className="text-fg-2" /> Reset demo mailbox
          </button>
        </div>
        <div className="px-4 pb-1 pt-4">
          <div className="flex items-center justify-between text-xs text-fg-3">
            <span className="flex items-center gap-1.5">
              <Icon name="cloud_done" size={16} /> Local storage
            </span>
            <span>
              {formatSize(used)} of {formatSize(quota)} used
            </span>
          </div>
          <div className="mt-2 h-1 overflow-hidden rounded-full bg-line">
            <div className="h-full rounded-full bg-accent" style={{ width: `${Math.min(100, (used / quota) * 100).toFixed(1)}%` }} />
          </div>
        </div>
        <div className="flex items-center justify-center gap-1 pb-1 pt-3 text-xs text-fg-3">
          <Icon name="lock" size={14} /> Mail is stored only in this browser
        </div>
      </Popover>
    </>
  );
}

import { useState } from "react";
import { act } from "../lib/actions";
import { isUnread } from "../lib/selectors";
import { useMail } from "../lib/store";
import type { Category, FolderId, Thread } from "../lib/types";
import { useUI } from "../lib/ui";
import { cn } from "../lib/utils";
import { LabelMenuButton, MoveMenuButton, SnoozeMenuButton } from "./menus";
import { Icon, IconButton, MenuDivider, MenuItem, Popover, useMenu } from "./ui";
import { CATEGORY_META } from "../lib/selectors";

export function ListToolbar({
  pageThreads,
  allThreads,
  folder,
  currentLabel,
  range,
  onPrev,
  onNext,
  compact,
}: {
  pageThreads: Thread[];
  allThreads: Thread[];
  folder?: FolderId;
  currentLabel?: string;
  range: { start: number; end: number; total: number };
  onPrev?: () => void;
  onNext?: () => void;
  compact?: boolean;
}) {
  const selected = useUI((s) => s.selected);
  const setSelected = useUI((s) => s.setSelected);
  const messages = useMail((s) => s.messages);
  const threads = useMail((s) => s.threads);
  const deliverNext = useMail((s) => s.deliverNext);
  const showToast = useUI((s) => s.showToast);
  const selectMenu = useMenu();
  const moreMenu = useMenu();
  const [refreshing, setRefreshing] = useState(false);

  const ids = selected.filter((id) => threads[id]);
  const pageIds = pageThreads.map((t) => t.id);
  const allOnPage = pageIds.length > 0 && pageIds.every((id) => ids.includes(id));
  const some = ids.length > 0 && !allOnPage;
  const anyUnread = ids.some((id) => threads[id] && isUnread(threads[id], messages));
  const anyStarred = ids.some((id) => threads[id]?.starred);
  const anyImportant = ids.some((id) => threads[id]?.important);
  const allSnoozed = ids.length > 0 && ids.every((id) => threads[id]?.snoozedUntil);

  const selectBy = (fn: (t: Thread) => boolean) => {
    setSelected(pageThreads.filter(fn).map((t) => t.id));
    selectMenu.close();
  };

  const refresh = () => {
    setRefreshing(true);
    window.setTimeout(() => {
      const got = deliverNext();
      setRefreshing(false);
      if (got.length) showToast({ message: `New message from ${got[0].from.name}.`, duration: 4000 });
    }, 650);
  };

  const hasSel = ids.length > 0;
  const btn = compact ? "sm" : "md";

  return (
    <div className="flex h-12 shrink-0 items-center gap-0.5 pl-2 pr-2 sm:pl-3">
      <div className="flex items-center rounded hover:bg-hover">
        <button
          type="button"
          role="checkbox"
          aria-checked={some ? "mixed" : allOnPage}
          aria-label="Select"
          data-tip="Select"
          onClick={() => setSelected(allOnPage || some ? [] : pageIds)}
          className="flex h-9 w-8 items-center justify-center"
        >
          <Icon
            name={some ? "indeterminate_check_box" : allOnPage ? "check_box" : "check_box_outline_blank"}
            fill={some || allOnPage}
            className={some || allOnPage ? "text-fg" : "text-fg-3"}
          />
        </button>
        <button ref={selectMenu.ref} type="button" aria-label="Select options" onClick={selectMenu.toggle} className="flex h-9 w-4 items-center justify-center">
          <Icon name="arrow_drop_down" size={18} className="-ml-1 text-fg-3" />
        </button>
      </div>
      <Popover anchor={selectMenu.ref.current} open={selectMenu.open} onClose={selectMenu.close} className="w-44">
        <MenuItem label="All" onClick={() => selectBy(() => true)} />
        <MenuItem label="None" onClick={() => selectBy(() => false)} />
        <MenuItem label="Read" onClick={() => selectBy((t) => !isUnread(t, messages))} />
        <MenuItem label="Unread" onClick={() => selectBy((t) => isUnread(t, messages))} />
        <MenuItem label="Starred" onClick={() => selectBy((t) => t.starred)} />
        <MenuItem label="Unstarred" onClick={() => selectBy((t) => !t.starred)} />
      </Popover>

      {!hasSel ? (
        <>
          <IconButton
            icon="refresh"
            label="Refresh"
            size={btn}
            onClick={refresh}
            iconClassName={refreshing ? "animate-spin-slow" : ""}
          />
          <IconButton ref={moreMenu.ref} icon="more_vert" label="More" size={btn} onClick={moreMenu.toggle} active={moreMenu.open} />
          <Popover anchor={moreMenu.ref.current} open={moreMenu.open} onClose={moreMenu.close} className="w-56">
            <MenuItem
              icon="done_all"
              label="Mark all as read"
              disabled={!allThreads.some((t) => isUnread(t, messages))}
              onClick={() => {
                moreMenu.close();
                act.setRead(
                  allThreads.filter((t) => isUnread(t, messages)).map((t) => t.id),
                  true,
                );
              }}
            />
            <MenuItem
              icon="select_all"
              label={`Select all ${allThreads.length}`}
              disabled={!allThreads.length}
              onClick={() => {
                moreMenu.close();
                setSelected(allThreads.map((t) => t.id));
              }}
            />
            {(folder === "trash" || folder === "spam") && (
              <>
                <MenuDivider />
                <MenuItem
                  icon="delete_forever"
                  label={folder === "trash" ? "Empty Trash" : "Delete all spam"}
                  danger
                  onClick={() => {
                    moreMenu.close();
                    act.empty(folder);
                  }}

import { useEffect, useMemo, useState, useSyncExternalStore } from "react";
import { parseHash, useHash } from "./router";
import { computeCounts, viewThreads } from "./selectors";
import { useMail } from "./store";
import type { View } from "./types";
import { useUI } from "./ui";

export function useMediaQuery(query: string) {
  return useSyncExternalStore(
    (cb) => {
      const mq = window.matchMedia(query);
      mq.addEventListener("change", cb);
      return () => mq.removeEventListener("change", cb);
    },
    () => window.matchMedia(query).matches,
  );
}

export const useIsMobile = () => useMediaQuery("(max-width: 767px)");
export const useIsNarrow = () => useMediaQuery("(max-width: 1023px)");

function systemDark() {
  return window.matchMedia("(prefers-color-scheme: dark)").matches;
}

export function useIsDark() {
  const theme = useMail((s) => s.settings.theme);
  const sys = useMediaQuery("(prefers-color-scheme: dark)");
  return theme === "dark" || (theme === "system" && sys);
}

export function useApplyTheme() {
  const dark = useIsDark();
  useEffect(() => {
    document.documentElement.classList.toggle("dark", dark);
    document.querySelector('meta[name="theme-color"]')?.setAttribute("content", dark ? "#111214" : "#f6f8fc");
  }, [dark]);
  return dark || systemDark();
}

export function useRoute() {
  const hash = useHash();
  return useMemo(() => parseHash(hash), [hash]);
}

/** With category tabs enabled, the plain Inbox shows the Primary tab. */
export function useEffectiveView(view: View): View {
  const inboxType = useMail((s) => s.settings.inboxType);
  return useMemo(() => {
    if (view.kind === "folder" && view.id === "inbox" && inboxType === "default") return { kind: "category", id: "primary" };
    return view;
  }, [view, inboxType]);
}

export function useViewThreads(view: View) {
  const threads = useMail((s) => s.threads);
  const messages = useMail((s) => s.messages);
  const labels = useMail((s) => s.labels);
  const now = useUI((s) => s.now);
  return useMemo(() => viewThreads(view, threads, messages, labels, now), [view, threads, messages, labels, now]);
}

export function useCounts() {
  const threads = useMail((s) => s.threads);
  const messages = useMail((s) => s.messages);
  const now = useUI((s) => s.now);
  return useMemo(() => computeCounts(threads, messages, now), [threads, messages, now]);
}

export function useDebouncedValue<T>(value: T, ms: number) {
  const [v, setV] = useState(value);
  useEffect(() => {
    const t = window.setTimeout(() => setV(value), ms);
    return () => window.clearTimeout(t);
  }, [value, ms]);
  return v;
}

import { useEffect, useRef, useState } from "react";
import { ComposeDock, ComposeFab } from "./components/Compose";
import { MailList } from "./components/MailList";
import { Dialogs, SettingsPanel, Toaster } from "./components/Overlays";
import { MobileDrawer, Sidebar } from "./components/Sidebar";
import { ThreadView } from "./components/ThreadView";
import { TopBar } from "./components/TopBar";
import { Icon, TooltipLayer } from "./components/ui";
import { openNewCompose } from "./lib/actions";
import { useApplyTheme, useCounts, useIsMobile, useIsNarrow, useRoute } from "./lib/hooks";
import { navigate } from "./lib/router";
import { useShortcuts } from "./lib/shortcuts";
import { useMail } from "./lib/store";
import type { ReadingPane, Route } from "./lib/types";
import { useUI } from "./lib/ui";
import { cn } from "./lib/utils";

function useTicker() {
  useEffect(() => {
    let lastNow = 0;
    const run = () => {
      const now = Date.now();
      const delivered = useMail.getState().tick(now);
      if (delivered.length || now - lastNow > 30_000) {
        lastNow = now;
        useUI.getState().setNow(now);
      }
      if (delivered.length && !useUI.getState().toast) {
        const d = delivered[delivered.length - 1];
        useUI.getState().showToast({
          message: `New message from ${d.from.name}`,
          action: { label: "Open", run: () => navigate(`#all/${d.threadId}`) },
          duration: 5000,
        });
      }
    };
    run();
    const id = window.setInterval(run, 5000);
    return () => window.clearInterval(id);
  }, []);
}

export default function App() {
  useApplyTheme();
  useShortcuts();
  useTicker();
  const route = useRoute();
  const isMobile = useIsMobile();
  const isNarrow = useIsNarrow();
  const readingPane = useMail((s) => s.settings.readingPane);
  const settingsOpen = useUI((s) => s.settingsOpen);
  const [fabExtended, setFabExtended] = useState(true);

  useEffect(() => {
    const h = () => openNewCompose();
    window.addEventListener("open-compose", h);
    return () => window.removeEventListener("open-compose", h);
  }, []);

  useEffect(() => {
    if (!isMobile) return;
    let last = 0;
    const onScroll = (e: Event) => {
      const el = e.target as HTMLElement;
      if (!el.closest?.("main")) return;
      const y = el.scrollTop;
      setFabExtended(y < 40 || y < last);
      last = y;
    };
    document.addEventListener("scroll", onScroll, true);
    return () => document.removeEventListener("scroll", onScroll, true);
  }, [isMobile]);

  const split = !isMobile && readingPane !== "none";

  return (
    <div className="flex h-dvh flex-col overflow-hidden bg-app text-fg">
      {!(isMobile && route.threadId) && <TopBar />}
      <div className="flex min-h-0 flex-1">
        {!isMobile && <Sidebar forceCollapsed={isNarrow} />}
        <main
          className={cn(
            "min-w-0 flex-1 overflow-hidden bg-surface transition-[margin] duration-200",
            !isMobile && "mb-4 mr-4 rounded-2xl",
            settingsOpen && !isMobile && "lg:mr-[356px]",
          )}
        >
          {split ? (
            <SplitView route={route} pane={readingPane} />
          ) : route.threadId ? (
            <ThreadView view={route.view} threadId={route.threadId} />
          ) : (
            <MailList view={route.view} />
          )}
        </main>
      </div>
      {isNarrow && <MobileDrawer />}
      <ComposeDock />
      {isMobile && !route.threadId && <ComposeFab extended={fabExtended} />}
      <Toaster />
      <Dialogs />
      <SettingsPanel />
      <TooltipLayer />
    </div>
  );
}

function SplitView({ route, pane }: { route: Route; pane: ReadingPane }) {
  const size = useMail((s) => s.settings.paneSize);
  const update = useMail((s) => s.updateSettings);
  const ref = useRef<HTMLDivElement>(null);
  const horizontal = pane === "right";
  const [dragging, setDragging] = useState(false);

  const onDown = (e: React.PointerEvent) => {
    e.preventDefault();
    setDragging(true);
    const rect = ref.current!.getBoundingClientRect();
    const move = (ev: PointerEvent) => {
      const pct = horizontal ? ((ev.clientX - rect.left) / rect.width) * 100 : ((ev.clientY - rect.top) / rect.height) * 100;
      update({ paneSize: Math.round(Math.min(72, Math.max(26, pct))) });
    };
    const up = () => {
      setDragging(false);
      window.removeEventListener("pointermove", move);
      window.removeEventListener("pointerup", up);
    };
    window.addEventListener("pointermove", move);
    window.addEventListener("pointerup", up);
  };

  return (
    <div ref={ref} className={cn("flex h-full", horizontal ? "flex-row" : "flex-col", dragging && "select-none")}>
      <div className="min-h-0 min-w-0 shrink-0 overflow-hidden" style={{ flexBasis: `${size}%` }}>
        <MailList view={route.view} activeThreadId={route.threadId} split />
      </div>
      <div
        role="separator"
        aria-orientation={horizontal ? "vertical" : "horizontal"}
        aria-label="Resize reading pane"
        onPointerDown={onDown}
        onDoubleClick={() => update({ paneSize: 42 })}
        className={cn(
          "group relative shrink-0 bg-line-soft transition-colors hover:bg-accent/40",
          horizontal ? "w-px cursor-col-resize" : "h-px cursor-row-resize",
          dragging && "bg-accent",
        )}
      >
        <span className={cn("absolute", horizontal ? "inset-y-0 -left-1.5 -right-1.5" : "inset-x-0 -bottom-1.5 -top-1.5")} />
      </div>
      <div className="min-h-0 min-w-0 flex-1 overflow-hidden">
        {route.threadId ? <ThreadView view={route.view} threadId={route.threadId} split /> : <EmptyPane />}
      </div>
    </div>
  );
}

function EmptyPane() {
  const counts = useCounts();
  return (
    <div className="flex h-full flex-col items-center justify-center gap-3 p-8 text-center text-fg-3">
      <Icon name="drafts" size={56} className="opacity-60" />
      <div className="font-display text-lg text-fg-2">No conversation selected</div>
      <div className="text-sm">
        {counts.inbox ? `${counts.inbox} unread in Primary` : "You're all caught up"} · Use <kbd className="rounded border border-line px-1">j</kbd>/<kbd className="rounded border border-line px-1">k</kbd> to move and{" "}
        <kbd className="rounded border border-line px-1">o</kbd> to open
      </div>
    </div>
  );
}

