  size = 20,
  className,
  style,
}: {
  name: string;
  fill?: boolean;
  size?: number;
  className?: string;
  style?: CSSProperties;
}) {
  const paths = ICON_PATHS[name];
  if (!paths && import.meta.env.DEV) console.warn(`Missing icon "${name}". Run: pnpm icons`);
  const d = (fill && paths?.[1]) || paths?.[0] || "";
  return (
    <svg
      aria-hidden
      viewBox="0 -960 960 960"
      width={size}
      height={size}
      fill="currentColor"
      className={cn("icon inline-block shrink-0", className)}
      style={style}
