  --font-display: "Google Sans", "Product Sans", "Roboto", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --shadow-row: inset 1px 0 0 var(--row-hover-edge), inset -1px 0 0 var(--row-hover-edge), 0 1px 2px 0 rgba(60, 64, 67, 0.3),
    0 1px 3px 1px rgba(60, 64, 67, 0.15);
  --shadow-pop: 0 4px 8px 3px rgba(0, 0, 0, 0.15), 0 1px 3px rgba(0, 0, 0, 0.3);
  --shadow-compose: 0 8px 10px 1px rgba(0, 0, 0, 0.14), 0 3px 14px 2px rgba(0, 0, 0, 0.12), 0 5px 5px -3px rgba(0, 0, 0, 0.2);
}

:root {
  --app-bg: #f6f8fc;
  --surface: #ffffff;
  --surface-2: #f2f6fc;
  --surface-3: #e9eef6;
  --raised: #ffffff;
  --text: #1f1f1f;
  --text-2: #444746;
  --text-3: #5e5e5e;
  --border: #e1e3e1;
  --border-soft: #eceff1;
  --accent: #0b57d0;
  --accent-soft: #d3e3fd;
  --on-accent-soft: #041e49;
  --primary: #0b57d0;
  --on-primary: #ffffff;
  --compose-btn: #c2e7ff;
  --on-compose: #001d35;
  --row-read: #f2f6fc;
  --row-unread: #ffffff;
  --row-selected: #c2dbff;
  --row-hover-edge: #dadce0;
  --hover: rgba(68, 71, 70, 0.08);
  --hover-strong: rgba(68, 71, 70, 0.14);
  --star: #f4b400;
  --danger: #d93025;
  --toast-bg: #303030;
  --toast-fg: #f2f2f2;
  --toast-action: #a8c7fa;
  color-scheme: light;
}

.dark {
  --app-bg: #111214;
  --surface: #1d1e20;
  --surface-2: #1d1e20;
  --surface-3: #2a2b2e;
  --raised: #2b2c2f;
  --text: #e3e3e3;
  --text-2: #c4c7c5;
  --text-3: #a3a6a8;
  --border: #3a3c3f;
  --border-soft: #2c2e31;
  --accent: #a8c7fa;
  --accent-soft: #004a77;
