    background: rgba(128, 128, 128, 0.35);
    border-radius: 10px;
    border: 2px solid transparent;
    background-clip: content-box;
  }
  *::-webkit-scrollbar-track {
    background: transparent;
  }

  button {
    cursor: pointer;
    font: inherit;
    color: inherit;
  }
  button:disabled {
    cursor: default;
  }

  :focus-visible {
    outline: 2px solid var(--accent);
    outline-offset: -2px;
  }
}

/* ─────────────── Email body typography ─────────────── */
.mail-body {
  font-size: 14px;
  line-height: 1.6;
  color: var(--text);
  overflow-wrap: anywhere;
}
.mail-body p {
  margin: 0 0 0.9em;
}
.mail-body ul,
.mail-body ol {
  margin: 0 0 0.9em;
  padding-left: 1.6em;
}
.mail-body ul {
  list-style: disc;
}
.mail-body ol {
  list-style: decimal;
}
.mail-body li {
  margin: 0.15em 0;
}
.mail-body a {
  color: var(--accent);
  text-decoration: underline;
  text-underline-offset: 2px;
}
.mail-body blockquote {
  margin: 0.4em 0 0.9em;
  padding-left: 12px;
  border-left: 2px solid var(--border);
  color: var(--text-3);
}
.mail-body code {
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 12.5px;
  background: var(--surface-3);
  padding: 1px 5px;
  border-radius: 4px;
}
.mail-body h1,
.mail-body h2,
.mail-body h3 {
  font-weight: 600;
}
.mail-body table {
  border-collapse: collapse;
}
.mail-body .gmail-signature {
  color: var(--text-3);
  margin-top: 0.8em;
}
.mail-body .gmail-quote-attr {
  color: var(--text-3);
  margin: 0.6em 0 0.4em;
}
.mail-body .gmail-quote {
  border-left: 1px solid #ccc;
  padding-left: 12px;
  margin-left: 4px;
}
.mail-body mark {
  background: #fde293;
  color: inherit;
  border-radius: 2px;
}
.dark .mail-body mark {
  background: #7a5c00;
}
.mail-rich {
  border-radius: 12px;
}
.dark .mail-rich {
  background: #f8f9fa;
  color: #202124;
  padding: 16px;
}
.dark .mail-rich a {
  color: inherit;
}

/* ─────────────── Compose editor ─────────────── */
.editor {
  outline: none;
  min-height: 100%;
  font-size: 14px;
  line-height: 1.55;
  overflow-wrap: anywhere;
}
.editor:empty::before {
  content: attr(data-placeholder);
  color: var(--text-3);
}
.editor ul {
  list-style: disc;
  padding-left: 1.6em;
}
.editor ol {
  list-style: decimal;
  padding-left: 1.6em;
}
.editor blockquote {
  border-left: 2px solid var(--border);
  padding-left: 12px;
  margin: 0.3em 0;
  color: var(--text-2);
}
.editor a {
  color: var(--accent);
  text-decoration: underline;
}
.editor .gmail-signature {
  color: var(--text-3);
}
.editor .gmail-fwd {
  color: var(--text-2);
}

/* ─────────────── Motion ─────────────── */
@keyframes pop-in {
  from {
    opacity: 0;
    transform: translateY(-4px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes slide-up {
  from {
    opacity: 0;
    transform: translateY(16px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
@keyframes slide-in-left {
  from {
    transform: translateX(-100%);
  }
  to {
    transform: none;
  }
}
@keyframes slide-in-right {
  from {
    transform: translateX(100%);
  }
  to {
    transform: none;
  }
}
@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}
.animate-pop {
  animation: pop-in 0.14s cubic-bezier(0.2, 0, 0, 1);
}
.animate-slide-up {
  animation: slide-up 0.22s cubic-bezier(0.2, 0, 0, 1);
}
.animate-fade {
  animation: fade-in 0.18s ease-out;
}
.animate-drawer {
  animation: slide-in-left 0.24s cubic-bezier(0.2, 0, 0, 1);
}
.animate-panel {
  animation: slide-in-right 0.24s cubic-bezier(0.2, 0, 0, 1);
}
.animate-spin-slow {
  animation: spin 0.9s linear infinite;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}

/* ─────────────── Print ─────────────── */
@media print {
  body {
    background: #fff !important;
  }
  body * {
    visibility: hidden;
  }
  .print-area,
  .print-area * {
    visibility: visible;
  }
  .print-area {
    position: absolute;
    inset: 0 auto auto 0;
    width: 100%;
  }
  .no-print {
    display: none !important;
  }
}

