      ) : (
        <div className="space-y-4 px-4 pb-2 pt-2">
          <label className="block text-sm text-fg-2">
            Date
            <input type="date" value={date} min={new Date(now).toISOString().slice(0, 10)} onChange={(e) => setDate(e.target.value)} className="mt-1 block h-10 w-full rounded-md border border-line bg-transparent px-3 text-fg" />
          </label>
          <label className="block text-sm text-fg-2">
