          ["Serif", "Georgia, 'Times New Roman', serif"],
          ["Fixed width", "ui-monospace, Menlo, monospace"],
          ["Wide", "'Arial Black', sans-serif"],
          ["Narrow", "'Arial Narrow', sans-serif"],
